import React from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';

export default function CurriculumBuilder({ modules, setModules }) {

  const addModule = () => {
    setModules([...modules, { title: '', content: [] }]);
  };

  const updateModuleTitle = (mIdx, val) => {
    const newModules = [...modules];
    newModules[mIdx].title = val;
    setModules(newModules);
  };

  const addItem = (mIdx, type) => {
    const newModules = [...modules];
    const newItem = type === 'video' 
      ? { type: 'video', title: '', videoUrl: '', uploadType: 'url' }
      : { 
          type: 'quiz', 
          title: '', 
          questions: [{ questionText: '', options: ['', '', '', ''], correctAnswer: 0 }] 
        };
    newModules[mIdx].content.push(newItem);
    setModules(newModules);
  };

  const updateItem = (mIdx, iIdx, updates) => {
    const newModules = [...modules];
    newModules[mIdx].content[iIdx] = { ...newModules[mIdx].content[iIdx], ...updates };
    setModules(newModules);
  };

  // QUIZ LOGIC: Add a new question to a specific quiz
  const addQuestion = (mIdx, iIdx) => {
    const newModules = [...modules];
    newModules[mIdx].content[iIdx].questions.push({
      questionText: '',
      options: ['', '', '', ''],
      correctAnswer: 0
    });
    setModules(newModules);
  };

  const updateQuestion = (mIdx, iIdx, qIdx, updates) => {
    const newModules = [...modules];
    newModules[mIdx].content[iIdx].questions[qIdx] = { 
      ...newModules[mIdx].content[iIdx].questions[qIdx], 
      ...updates 
    };
    setModules(newModules);
  };

  // VIDEO LOGIC: Upload file from PC
  const handleFileUpload = async (mIdx, iIdx, file) => {
    const formData = new FormData();
    formData.append('video', file);
    updateItem(mIdx, iIdx, { isUploading: true });

    try {
      const { data } = await axios.post('/api/upload/video', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      updateItem(mIdx, iIdx, { videoUrl: data.url, uploadType: 'local', isUploading: false });
      toast.success("Video uploaded!");
    } catch (err) {
      updateItem(mIdx, iIdx, { isUploading: false });
      toast.error("Upload failed");
    }
  };

  return (
    <div className="glass" style={{ padding: 24, marginTop: 32, borderRadius: 20 }}>
      <h3 style={{ marginBottom: 20 }}>Course Curriculum</h3>

      {modules.map((mod, mIdx) => (
        <div key={mIdx} style={{ marginBottom: 30, padding: 20, background: 'rgba(255,255,255,0.03)', borderRadius: 12 }}>
          <input 
            className="input" 
            placeholder="Module Title" 
            value={mod.title} 
            onChange={e => updateModuleTitle(mIdx, e.target.value)} 
            style={{ fontWeight: 'bold', marginBottom: 15 }}
          />

          {mod.content.map((item, iIdx) => (
            <div key={iIdx} style={{ marginLeft: 20, marginBottom: 15, padding: 15, background: 'rgba(0,0,0,0.2)', borderRadius: 10 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', color: '#7c3aed', fontSize: 12, fontWeight: 800, marginBottom: 10 }}>
                <span>{item.type.toUpperCase()}</span>
              </div>

              <input 
                className="input-sm" 
                placeholder="Title" 
                value={item.title} 
                onChange={e => updateItem(mIdx, iIdx, { title: e.target.value })} 
              />

              {item.type === 'video' && (
                <div style={{ marginTop: 10 }}>
                  <input 
                    className="input-sm" 
                    placeholder="YouTube URL" 
                    value={item.videoUrl} 
                    onChange={e => updateItem(mIdx, iIdx, { videoUrl: e.target.value, uploadType: 'url' })} 
                  />
                  <div style={{ margin: '10px 0', fontSize: 11, color: '#6b6490', textAlign: 'center' }}>OR</div>
                  <input type="file" accept="video/*" onChange={e => handleFileUpload(mIdx, iIdx, e.target.files[0])} />
                  {item.isUploading && <p style={{ color: '#00f5d4', fontSize: 12 }}>Uploading...</p>}
                </div>
              )}

              {item.type === 'quiz' && (
                <div style={{ marginTop: 15 }}>
                  {item.questions.map((q, qIdx) => (
                    <div key={qIdx} style={{ marginBottom: 15, padding: 10, background: 'rgba(255,255,255,0.05)', borderRadius: 8 }}>
                      <input 
                        className="input-sm" 
                        placeholder={`Question ${qIdx + 1}`} 
                        value={q.questionText} 
                        onChange={e => updateQuestion(mIdx, iIdx, qIdx, { questionText: e.target.value })}
                      />
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginTop: 10 }}>
                        {q.options.map((opt, oIdx) => (
                          <div key={oIdx} style={{ display: 'flex', gap: 5 }}>
                            <input 
                              type="radio" 
                              checked={q.correctAnswer === oIdx} 
                              onChange={() => updateQuestion(mIdx, iIdx, qIdx, { correctAnswer: oIdx })} 
                            />
                            <input 
                              className="input-xs" 
                              value={opt} 
                              placeholder={`Option ${oIdx + 1}`}
                              onChange={e => {
                                const newOpts = [...q.options];
                                newOpts[oIdx] = e.target.value;
                                updateQuestion(mIdx, iIdx, qIdx, { options: newOpts });
                              }}
                            />
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                  <button className="btn-sm" onClick={() => addQuestion(mIdx, iIdx)}>+ Add Question</button>
                </div>
              )}
            </div>
          ))}

          <div style={{ display: 'flex', gap: 10, marginTop: 10 }}>
            <button className="btn-ghost btn-sm" onClick={() => addItem(mIdx, 'video')}>+ Video</button>
            <button className="btn-ghost btn-sm" onClick={() => addItem(mIdx, 'quiz')}>+ Quiz</button>
          </div>
        </div>
      ))}

      <button className="btn btn-primary" style={{ width: '100%' }} onClick={addModule}>+ Add Module</button>
    </div>
  );
}
